// Construction de la liste plate, ordonnée par secteur (ordre pédagogique)
// et par rang de fréquence global croissant.
const VOCAB_WORDS = (() => {
  const list = [];
  let rank = 1;
  for (const sector of VOCAB_SECTORS) {
    const words = RAW_VOCAB[sector.id] || [];
    words.forEach(([en, fr], i) => {
      list.push({
        id: `${sector.id}-${String(i + 1).padStart(2, "0")}`,
        en, fr,
        sector: sector.id,
        rank: rank++,
      });
    });
  }
  return list;
})();

const VOCAB_BY_ID = Object.fromEntries(VOCAB_WORDS.map(w => [w.id, w]));
